#!/usr/bin/env bash
# Create Secret besu-rpc-nodekey (key `nodekey`, 32 random bytes as hex) INSIDE the party namespace; generated by openssl, piped to kubectl,
# never written to a file, never printed (final-design/stealth/PLAN.md S4: "its own node key is generated in the ns").
#   KUBECONFIG=<party kubeconfig> ./nodekey.sh <bi|bank-a|bank-b|bank-c>
set -euo pipefail
party="${1:?usage: nodekey.sh <bi|bank-a|bank-b|bank-c>}"
case "$party" in bi|bank-a|bank-b|bank-c) ;; *) echo "nodekey.sh: unknown party '$party'" >&2; exit 2 ;; esac
command -v openssl >/dev/null || { echo "nodekey.sh: openssl missing" >&2; exit 2; }
kubectl -n "rd-stealth-$party" create secret generic besu-rpc-nodekey --from-file=nodekey=<(openssl rand -hex 32)
echo "nodekey.sh: Secret besu-rpc-nodekey is in rd-stealth-$party (value not shown)"
